@startuml

class Hospital {}

class Office {}

class User {}

class Doctor extends User {}

class Patient extends User {}

class Schedule {
  + Date : date
  + StartTime : time
  + EndTime : time
}

abstract class Appointment {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class BloodTest extends Appointment {}

class Consultation extends Appointment {}

class Surgery extends Appointment {}

Hospital "1" -- "*" Office
Doctor "1" -- "*" Schedule : creates
Office "1" -- "*" Schedule
Doctor "1" -- "*" Appointment : has
Patient "1" -- "*" Appointment : books
Appointment "*" -- "1" Schedule : for

